CREATE TRIGGER script_versions_immutable BEFORE UPDATE ON script_versions WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.research_version_id IS NOT OLD.research_version_id OR NEW.version_no IS NOT OLD.version_no OR NEW.script_json IS NOT OLD.script_json OR NEW.content_hash IS NOT OLD.content_hash OR NEW.target_duration_ms IS NOT OLD.target_duration_ms OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'VERSION_IMMUTABLE'); END;
